const text = $input.first().json.text;
const chunkSize = 500;
const chunkOverlap = 50;
const chunks = [];

for (let i = 0; i < text.length; i += chunkSize - chunkOverlap) {
  const chunk = text.substring(i, i + chunkSize);
  if (chunk.trim().length > 0) {
    chunks.push({ json: { text: chunk, chunkIndex: chunks.length } });
  }
}

return chunks;

const items = $input.all();
const VECTOR_SIZE = 256;

function textToVector(text, size) {
  const vector = new Array(size).fill(0);
  const normalized = text.toLowerCase().replace(/[^\u0430-\u044fa-z0-9]/g, ' ');
  const words = normalized.split(/\s+/).filter(w => w.length > 0);
  for (const word of words) {
    for (let i = 0; i < word.length; i++) {
      const ch = word.charCodeAt(i);
      vector[ch % size] += 1;
      vector[(ch * 31) % size] += 0.5;
    }
  }
  const norm = Math.sqrt(vector.reduce((s, v) => s + v * v, 0));
  if (norm > 0) {
    for (let i = 0; i < size; i++) vector[i] /= norm;
  }
  return vector;
}

const points = [];
for (let i = 0; i < items.length; i++) {
  const text = items[i].json.text;
  const vector = textToVector(text, VECTOR_SIZE);
  points.push({
    id: i + 1,
    vector: vector,
    payload: { text: text, source: 'faq' }
  });
}

return [{ json: { points: points, count: points.length } }];

