const body = $input.first().json.body || $input.first().json;
const result = body.result || {};
const points = result.points || [];
const query = $('Подготовка').first().json.query;

const queryWords = query.toLowerCase().replace(/[^\u0430-\u044fa-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 2);

const scored = [];
for (const p of points) {
  const text = (p.payload?.text || '').toLowerCase();
  let score = 0;
  for (const word of queryWords) {
    if (text.includes(word)) score += 1;
  }
  if (score > 0) {
    scored.push({ text: p.payload.text, score: score });
  }
}

scored.sort((a, b) => b.score - a.score);
const top = scored.slice(0, 4);

if (top.length === 0) {
  return [{ json: { context: '', query: query, found: false } }];
}

const ctx = top.map((s) => s.text).join('\n\n');
return [{ json: { context: ctx, query: query, found: true } }];

